import { create } from 'zustand'; import { persist } from 'zustand/middleware'; import type { Hospital,HospitalStaff,HospitalUser } from '../types/models'
export const TOKEN_KEY='careos-hospital-token'
type S={token:string|null;user:HospitalUser|null;hospital:Hospital|null;staff:HospitalStaff|null;isAuthenticated:boolean;setSession:(p:{token:string;user:HospitalUser;hospital:Hospital;staff:HospitalStaff})=>void;restoreSession:(p:{user:HospitalUser;hospital:Hospital;staff:HospitalStaff})=>void;clearSession:()=>void}
export const useAuthStore=create<S>()(persist((set,get)=>({token:localStorage.getItem(TOKEN_KEY),user:null,hospital:null,staff:null,isAuthenticated:Boolean(localStorage.getItem(TOKEN_KEY)),setSession:p=>{localStorage.setItem(TOKEN_KEY,p.token);set({...p,isAuthenticated:true})},restoreSession:p=>set({...p,token:get().token||localStorage.getItem(TOKEN_KEY),isAuthenticated:true}),clearSession:()=>{localStorage.removeItem(TOKEN_KEY);set({token:null,user:null,hospital:null,staff:null,isAuthenticated:false})}}),{name:'careos-hospital-auth',partialize:s=>({user:s.user,hospital:s.hospital,staff:s.staff})}))
